messages.content:
Generate release-note suggestion variants from the full diff evidence.
Use the file patches as the primary source of truth. Do not infer behavior from titles alone.
Return only JSON that matches the requested schema. Do not include Markdown fences or prose.
For each item, return exactly 1 suggestion string(s) in the suggestions array.
Do not combine items, rename item ids, omit an item, or mention implementation details unless they matter to release-note readers.
If a file has no semantic_diff (and patch_available=false), treat that file as changed but do not invent unavailable details.
Input JSON:
{
  "items": [
    {
      "classification": {
        "area": "general",
        "audience": "external",
        "kind": "changed",
        "semver": "patch"
      },
      "commits": [
        {
          "author": "Verlato",
          "message": "docs: tune release note copy",
          "sha": "doctor",
          "subject": "docs: tune release note copy"
        }
      ],
      "current_summary": "Checks whether the selected model can produce structured suggestions from diff evidence.",
      "diff_summary": {
        "api_changes": [],
        "config_changes": [],
        "file_statuses": {
          "docs/release-notes.md": "M"
        },
        "files_by_area": {
          "docs": [
            "docs/release-notes.md"
          ]
        },
        "migration_changes": [],
        "summary": "M docs/release-notes.md"
      },
      "file_count": 1,
      "files": [
        {
          "patch": "@@ -1,2 +1,2 @@\n-Old release note text\n+Clearer release note text for external readers\n",
          "patch_available": true,
          "patch_chars": 86,
          "patch_unavailable_reason": "",
          "path": "docs/release-notes.md",
          "status": "M"
        }
      ],
      "item_id": "doctor_model",
      "labels": [],
      "missing_patch_count": 0,
      "patch_chars": 86,
      "pr": null,
      "title": "Doctor model diff probe"
    }
  ],
  "prompt_shape": "full-diff-json-v1",
  "style_profile": {
    "banned_phrases": [],
    "guidance": "",
    "project_vocabulary": [],
    "specificity_floor": 0.0
  },
  "suggestion_count": 1,
  "tone": "release-note"
}
